package com.brainserve.onboarding.payments.infrastructure.persistence;
import com.brainserve.onboarding.payments.domain.model.Refund;import jakarta.persistence.LockModeType;import java.util.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;
public interface RefundRepository extends JpaRepository<Refund,UUID>{Optional<Refund> findByOrganizationIdAndId(UUID org,UUID id);Optional<Refund> findByOrganizationIdAndPaymentIdAndIdempotencyKey(UUID org,UUID paymentId,String key);Optional<Refund> findByProviderAndProviderRefundId(String provider,String providerRefundId);@Lock(LockModeType.PESSIMISTIC_WRITE)@Query("select r from Refund r where r.organizationId=:org and r.id=:id")Optional<Refund> findForUpdate(@Param("org")UUID org,@Param("id")UUID id);List<Refund> findAllByOrganizationIdAndInvoiceIdOrderByRequestedAtDescIdDesc(UUID org,UUID invoiceId);List<Refund> findAllByOrganizationIdAndPaymentIdOrderByRequestedAtDescIdDesc(UUID org,UUID paymentId);}
